mapper.select:
SELECT m.id, m.name, m.movie_key, m.tmdb_id, m.deleted, m.kind, to_char(m.release_date, 'YYYY-MM-DD') AS release_date, (SELECT count(*) FROM movie_show_time st WHERE st.movie_id = m.id AND st.deleted = 0) AS show_count, AS reference_summary FROM movie m WHERE m.kind = 'movie' AND ( m.name ILIKE ('%' || #{keyword} || '%') OR m.movie_key = #{keyword}
OR m.id = #{keywordNum} OR m.tmdb_id = #{keywordNum}
) ORDER BY m.deleted ASC, (m.tmdb_id IS NOT NULL) DESC, m.id ASC LIMIT 50

mapper.delete:
DELETE FROM movie_rate r
 WHERE r.movie_id = #{loserId}
   AND EXISTS (
     SELECT 1 FROM movie_rate s
      WHERE s.movie_id = #{survivorId}
        AND s.user_id = r.user_id
   )

DELETE FROM movie_staff l
 WHERE l.movie_id = #{loserId}
   AND EXISTS (
     SELECT 1 FROM movie_staff s
      WHERE s.movie_id = #{survivorId}
        AND s.staff_id IS NOT DISTINCT FROM l.staff_id
        AND s.position_id IS NOT DISTINCT FROM l.position_id
   )

DELETE FROM movie_character l
 WHERE l.movie_id = #{loserId}
   AND EXISTS (
     SELECT 1 FROM movie_character s
      WHERE s.movie_id = #{survivorId}
        AND s.character_id IS NOT DISTINCT FROM l.character_id
   )

mapper.update:
UPDATE ${table} t SET deleted = 1 WHERE t.movie_id = #{survivorId} AND t.deleted = 0 AND EXISTS ( SELECT 1 FROM ${table} t2 WHERE t2.movie_id = t.movie_id AND t2.deleted = 0 AND t2.id < t.id
AND t2.${col} IS NOT DISTINCT FROM t.${col}
)

UPDATE movie
   SET deleted = 1, update_time = CURRENT_TIMESTAMP
 WHERE id = #{id}
